-- ============================================================
-- SEED: Módulo 17 — Non-Defining Relative Clauses (B2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'non-defining-clauses';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo non-defining-clauses não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: Non-Defining Clauses with WHO
  (cid,1,1,'gap_fill','Professor Nakamura, _____ has published over 50 papers, is retiring next year.','who',NULL,'Use "who" (not "that") in non-defining relative clauses about people. The clause adds extra, non-essential information.','easy'),
  (cid,1,2,'multiple_choice','My mother, _____ is a retired nurse, gives excellent medical advice.','who','["that","which","whose","who"]','"Who" is used for people in non-defining clauses. "That" is NEVER used in non-defining relative clauses.','easy'),
  (cid,1,3,'gap_fill','The president, _____ delivered a speech yesterday, announced new economic policies.','who',NULL,'Non-defining clause with "who" adds extra information about the president (already identified).','easy'),
  (cid,1,4,'multiple_choice','Darwin, _____ developed the theory of evolution, published On the Origin of Species in 1859.','who','["that","which","whom","who"]','"Who" for people. "That" cannot be used in non-defining clauses. → Darwin, who developed...','easy'),
  (cid,1,5,'gap_fill','The researchers, _____ had worked on the project for five years, were disappointed by the results.','who',NULL,'Non-defining: the researchers are already identified. "Who" introduces additional background information.','medium'),
  (cid,1,6,'multiple_choice','Dr. Patel, _____ I worked with during my internship, is now a leading cardiologist.','whom','["who","that","which","whom"]','When the relative pronoun is the object of the clause, "whom" is more formal and correct. → Dr. Patel, whom I worked with.','hard'),
  (cid,1,7,'gap_fill','The students, _____ had studied all week, were confident going into the exam.','who',NULL,'Non-defining clause: adds extra information about already-identified students.','easy'),
  (cid,1,8,'multiple_choice','Marie Curie, _____ won two Nobel Prizes, remains one of the most celebrated scientists in history.','who','["that","which","whom","who"]','Non-defining clause about a specific, named person → "who."','easy'),

  -- BLOCK 2: Non-Defining Clauses with WHICH
  (cid,2,9,'gap_fill','The experiment, _____ was conducted over three years, produced remarkable results.','which',NULL,'Use "which" (not "that") for things in non-defining relative clauses. The clause adds extra, parenthetical information.','easy'),
  (cid,2,10,'multiple_choice','The Amazon rainforest, _____ covers over 5.5 million square kilometers, is vital for global biodiversity.','which','["that","who","whose","which"]','"Which" is used for things in non-defining clauses. "That" cannot be used here.','easy'),
  (cid,2,11,'gap_fill','Her latest book, _____ was published in January, has already sold a million copies.','which',NULL,'Non-defining clause adds extra information about the book (already identified as "her latest book").','easy'),
  (cid,2,12,'multiple_choice','The treaty, _____ was signed in 1997, set binding limits on greenhouse gas emissions.','which','["that","who","whom","which"]','Non-defining clause about a thing (the treaty) → "which."','easy'),
  (cid,2,13,'gap_fill','The new policy, _____ takes effect next month, will affect millions of workers.','which',NULL,'Non-defining clause with "which" provides additional, non-essential information about the policy.','medium'),
  (cid,2,14,'multiple_choice','The Great Barrier Reef, _____ stretches over 2,300 kilometers, is threatened by rising ocean temperatures.','which','["that","who","whose","which"]','Named, unique entity → non-defining clause → "which."','easy'),
  (cid,2,15,'gap_fill','The software, _____ was developed by a small team, has transformed the industry.','which',NULL,'"Which" for things in non-defining clauses. Note the commas around the clause.','easy'),
  (cid,2,16,'multiple_choice','The discovery of penicillin, _____ happened by accident in 1928, saved millions of lives.','which','["that","who","whose","which"]','Non-defining clause about an event (a thing) → "which."','medium'),

  -- BLOCK 3: Non-Defining Clauses with WHOSE & WHERE
  (cid,3,17,'gap_fill','The scientist, _____ research on genetics is world-renowned, will give the keynote speech.','whose',NULL,'"Whose" shows possession in relative clauses for both people and things. → the scientist whose research.','medium'),
  (cid,3,18,'multiple_choice','The company, _____ headquarters are in Tokyo, employs over 50,000 people worldwide.','whose','["which","that","who","whose"]','"Whose" for possession with things (company). → the company, whose headquarters.','medium'),
  (cid,3,19,'gap_fill','The Amazon basin, _____ rivers drain into the Atlantic Ocean, supports extraordinary biodiversity.','whose',NULL,'"Whose" shows possession with a geographical feature. → the Amazon basin, whose rivers.','hard'),
  (cid,3,20,'multiple_choice','The laboratory, _____ the Nobel Prize winner conducted her research, was recently renovated.','where','["which","that","whose","where"]','"Where" is used for places in relative clauses. → the laboratory, where she conducted her research.','medium'),
  (cid,3,21,'gap_fill','Oxford University, _____ both C.S. Lewis and J.R.R. Tolkien taught, is one of the world''s oldest institutions.','where',NULL,'"Where" refers to a location. Non-defining clause adds extra historical information.','medium'),
  (cid,3,22,'multiple_choice','Dr. Chen, _____ publications have been cited over 10,000 times, is considered a pioneer in the field.','whose','["who","which","that","whose"]','"Whose" indicates possession. → Dr. Chen, whose publications have been cited.','medium'),
  (cid,3,23,'gap_fill','The conference center, _____ the annual summit is held, is located in Geneva.','where',NULL,'"Where" in a non-defining clause identifies the location. → the conference center, where the summit is held.','medium'),
  (cid,3,24,'multiple_choice','The author, _____ debut novel won the Booker Prize, is now working on her second book.','whose','["who","which","that","whose"]','"Whose" shows possession (the author''s debut novel). → the author, whose debut novel.','medium'),

  -- BLOCK 4: CANNOT Use "That" — Contrast & Error Identification
  (cid,4,25,'multiple_choice','Which sentence is grammatically correct?','Professor Kim, who teaches linguistics, has written a new textbook.','["Professor Kim, that teaches linguistics, has written a new textbook.","Professor Kim, who teaches linguistics, has written a new textbook.","Professor Kim who teaches linguistics has written a new textbook.","Professor Kim, which teaches linguistics, has written a new textbook."]','"That" CANNOT be used in non-defining relative clauses. Commas are required. → Professor Kim, who teaches...','medium'),
  (cid,4,26,'multiple_choice','Identify the error: "The Eiffel Tower, that was built in 1889, attracts millions of tourists each year."','Replace "that" with "which"','["Replace commas with no punctuation","Replace \"that\" with \"which\"","Remove the relative clause","Replace \"was built\" with \"built\""]','"That" cannot be used in non-defining relative clauses. The correct pronoun for a thing is "which."','medium'),
  (cid,4,27,'gap_fill','Correct the error: "The Nile River, that flows through eleven countries, is the longest river in Africa." → The Nile River, _____ flows through eleven countries, is the longest river in Africa.','which',NULL,'"That" cannot begin a non-defining relative clause. Replace with "which" for things.','medium'),
  (cid,4,28,'multiple_choice','Which sentence uses non-defining clauses correctly?','The human brain, which contains approximately 86 billion neurons, is the most complex organ in the body.','["The human brain that contains approximately 86 billion neurons is the most complex organ.","The human brain, that contains approximately 86 billion neurons, is the most complex organ.","The human brain, which contains approximately 86 billion neurons, is the most complex organ in the body.","The human brain which contains approximately 86 billion neurons is the most complex organ."]','Non-defining clause requires commas and "which" (not "that"). → The human brain, which contains...','medium'),
  (cid,4,29,'gap_fill','Distinguish: "The student _____ scored highest won a scholarship." (defining — identifies which student)','who/that',NULL,'Defining relative clause (no commas) — "that" or "who" can be used to identify which student.','medium'),
  (cid,4,30,'gap_fill','Distinguish: "Maria, _____ scored highest in the class, won a scholarship." (non-defining — extra info)','who',NULL,'Non-defining relative clause — "who" only (no "that"). Commas are required.','medium'),
  (cid,4,31,'multiple_choice','Which sentence is a non-defining relative clause?','Tokyo, which is the capital of Japan, has a population of over 13 million.','["The city that has the largest population is Tokyo.","Tokyo, which is the capital of Japan, has a population of over 13 million.","The students who pass will receive certificates.","The book that she wrote became a bestseller."]','Non-defining: adds extra info about a named entity (Tokyo). Commas + "which" are the key markers.','easy'),
  (cid,4,32,'multiple_choice','Identify the sentence with a correctly punctuated non-defining clause.','The Sahara Desert, which is located in North Africa, is the largest hot desert in the world.','["The Sahara Desert which is located in North Africa is the largest hot desert in the world.","The Sahara Desert, that is located in North Africa, is the largest hot desert.","The Sahara Desert, which is located in North Africa, is the largest hot desert in the world.","The Sahara Desert which located in North Africa is the largest hot desert."]','Non-defining clauses require commas. "Which" is used for things. → The Sahara Desert, which is located...','easy'),

  -- BLOCK 5: TOEFL Academic – Non-Defining Clauses in Context
  (cid,5,33,'gap_fill','[TOEFL Reading] The study, _____ was peer-reviewed by six independent experts, confirms previous findings on climate change.','which',NULL,'Non-defining clause about a thing (the study). "Which" required, not "that."','medium'),
  (cid,5,34,'multiple_choice','[TOEFL Reading] The hypothesis, _____ had been debated for over a decade, was finally confirmed by the new data.','which','["that","who","whose","which"]','Non-defining clause with "which" for a thing (hypothesis). Commas required.','medium'),
  (cid,5,35,'gap_fill','[TOEFL Listening] The professor, _____ specializes in neuroscience, argued that sleep is critical for memory consolidation.','who',NULL,'Non-defining clause: the professor is already identified. "Who" adds extra background information.','medium'),
  (cid,5,36,'multiple_choice','[TOEFL Reading] The methodology, _____ was described in detail in Section 2, allowed for precise measurement of variables.','which','["that","who","whom","which"]','Non-defining clause about methodology (a thing) → "which."','medium'),
  (cid,5,37,'gap_fill','[TOEFL Reading] The participants, _____ ages ranged from 18 to 65, were randomly assigned to two groups.','whose',NULL,'"Whose" shows possession with people (the participants'' ages). → whose ages ranged from 18 to 65.','hard'),
  (cid,5,38,'multiple_choice','[TOEFL Listening] The lecture hall, _____ the experiment was demonstrated, seats over 300 students.','where','["which","that","whose","where"]','"Where" for places in relative clauses. → the lecture hall, where the experiment was demonstrated.','medium'),
  (cid,5,39,'gap_fill','[TOEFL Reading] Einstein, _____ work on relativity revolutionized physics, was awarded the Nobel Prize in 1921.','whose',NULL,'"Whose" for possession. → Einstein, whose work on relativity revolutionized physics.','medium'),
  (cid,5,40,'multiple_choice','[TOEFL Reading] The 1987 Montreal Protocol, _____ aimed to reduce ozone-depleting substances, is considered one of the most successful international agreements.','which','["that","who","whose","which"]','Named treaty (a thing) → non-defining clause → "which." "That" cannot be used here.','medium'),

  -- BLOCK 6: TOEFL Academic – Reduction to Participle Clauses
  (cid,6,41,'gap_fill','[TOEFL Reading] The report, _____ (publish) in 2019, highlighted the need for immediate action on deforestation. (Reduce to participial phrase)','published',NULL,'Non-defining clause "which was published" can be reduced to "published." → The report, published in 2019...','hard'),
  (cid,6,42,'multiple_choice','[TOEFL Reading] Reduce: "The government, which introduced the policy in 2015, claims it has been effective."','The government, having introduced the policy in 2015, claims it has been effective.','["The government, introduced the policy in 2015, claims it has been effective.","The government, having introduced the policy in 2015, claims it has been effective.","The government, introducing the policy in 2015, claims it has been effective.","The government, to introduce the policy in 2015, claims it has been effective."]','"Which introduced" reduces to "having introduced" (perfect participle for completed action before main verb).','hard'),
  (cid,6,43,'gap_fill','[TOEFL Reading] The data, _____ (collect) over five years, suggest a clear correlation between pollution and respiratory illness. (Reduce to participial phrase)','collected',NULL,'"Which was collected" reduces to "collected." → The data, collected over five years, suggest...','hard'),
  (cid,6,44,'multiple_choice','[TOEFL Reading] Which reduced form is correct? "The theory, _____ multiple fields of study, has influenced modern science."','spanning','["spanned","to span","which spanning","spanning"]','"Which spans" reduces to "spanning" (present participle for ongoing/active description).','hard'),
  (cid,6,45,'gap_fill','[TOEFL Listening] The molecule, _____ (discover) in 1953, plays a crucial role in genetic coding.','discovered',NULL,'"Which was discovered" → passive participle "discovered." → The molecule, discovered in 1953...','hard'),
  (cid,6,46,'multiple_choice','[TOEFL Reading] "The researcher, _____ in behavioral psychology, published her findings in Nature."','specializing','["specialized","having specialized","specializing","to specialize"]','"Who specializes" reduces to "specializing" (present participle for ongoing trait or characteristic).','hard'),
  (cid,6,47,'gap_fill','[TOEFL Reading] The manuscript, _____ (write) in the 14th century, provides valuable insights into medieval life.','written',NULL,'"Which was written" reduces to "written" (past participle). → The manuscript, written in the 14th century...','hard'),
  (cid,6,48,'multiple_choice','[TOEFL Reading] "The volcano, _____ last in 1980, remains dormant but potentially active."','which erupted','["erupting","having erupting","which erupted","erupted"]','When a past participle would be ambiguous, the full non-defining clause "which erupted" is preferable.','hard'),

  -- BLOCK 7: TOEFL Academic – Clauses Adding Whole-Sentence Comments
  (cid,7,49,'gap_fill','[TOEFL Reading] She passed all her exams, _____ surprised even her professors.','which',NULL,'"Which" can refer back to the whole previous clause (not just a noun). → She passed, which surprised...','hard'),
  (cid,7,50,'multiple_choice','[TOEFL Reading] The team discovered a new species, _____ was later named after the lead researcher.','which','["that","who","whose","which"]','"Which" refers to "a new species" (thing). Non-defining, adds information about what happened after.','medium'),
  (cid,7,51,'gap_fill','[TOEFL Listening] The budget was cut by 30%, _____ forced the department to abandon several projects.','which',NULL,'"Which" here refers back to the entire preceding clause (the budget cut). This is a common academic usage.','hard'),
  (cid,7,52,'multiple_choice','[TOEFL Reading] "The samples were contaminated, _____ meant the entire experiment had to be repeated."','which','["that","what","whose","which"]','"Which" can refer to a whole situation/event. "What" cannot be used here after a comma.','hard'),
  (cid,7,53,'gap_fill','[TOEFL Reading] Professor Hayes retired last year, _____ left the department without a senior researcher.','which',NULL,'Non-defining clause with "which" commenting on the whole situation. → Professor Hayes retired, which left...','hard'),
  (cid,7,54,'multiple_choice','[TOEFL Reading] The survey was completed by 1,200 participants, _____ made the sample statistically significant.','which','["that","who","whose","which"]','"Which" refers to the entire fact (1,200 participants completing the survey). → which made it significant.','hard'),
  (cid,7,55,'gap_fill','[TOEFL Listening] The talks broke down in December, _____ led to renewed military tensions.','which',NULL,'"Which" can refer to an event or situation. → The talks broke down, which led to...','hard'),
  (cid,7,56,'multiple_choice','[TOEFL Reading] New evidence emerged in 2023, _____ challenged the prevailing theory on human migration.','which','["that","who","whose","which"]','"Which" for things/events in non-defining clauses. → New evidence emerged, which challenged...','medium'),

  -- BLOCK 8: TOEFL Academic – Mixed Practice
  (cid,8,57,'gap_fill','[TOEFL Reading] The findings, _____ were corroborated by three independent laboratories, suggest a breakthrough in cancer treatment.','which',NULL,'"Which" in a non-defining clause about findings (a thing). Note the commas.','medium'),
  (cid,8,58,'multiple_choice','[TOEFL Reading] Select the sentence with the correct non-defining relative clause.','The Hubble Telescope, which was launched in 1990, has transformed our understanding of the universe.','["The Hubble Telescope that was launched in 1990 has transformed our understanding.","The Hubble Telescope, which was launched in 1990, has transformed our understanding of the universe.","The Hubble Telescope, that was launched in 1990, has transformed our understanding.","The Hubble Telescope which launched in 1990 has transformed our understanding."]','Correct: commas + "which" (not "that") for a named, unique object.','medium'),
  (cid,8,59,'gap_fill','[TOEFL Listening] The author, _____ latest book examines the ethics of AI, will speak at the conference.','whose',NULL,'"Whose" for possession. → the author, whose latest book examines...','medium'),
  (cid,8,60,'multiple_choice','[TOEFL Reading] "The data center, _____ the servers are housed, uses 100% renewable energy."','where','["which","that","whose","where"]','"Where" for places. → the data center, where the servers are housed.','medium'),
  (cid,8,61,'gap_fill','[TOEFL Reading] The article, _____ has been cited over 500 times, remains a landmark in sociological research.','which',NULL,'Non-defining clause. "Which" for a thing (the article). Commas required.','easy'),
  (cid,8,62,'multiple_choice','[TOEFL Listening] "Dr. Foster, _____ opinion I respect greatly, disagrees with the committee''s conclusion."','whose','["who","which","that","whose"]','"Whose opinion" = possessive. → Dr. Foster, whose opinion I respect greatly.','hard'),
  (cid,8,63,'gap_fill','[TOEFL Reading] The glacier, _____ has retreated by 40% since 1980, provides freshwater to millions of people.','which',NULL,'Non-defining clause about a thing (the glacier). → the glacier, which has retreated...','medium'),
  (cid,8,64,'multiple_choice','[TOEFL Reading] Identify the correct sentence.','The conference, which was attended by over 2,000 delegates, produced a landmark agreement on climate finance.','["The conference that was attended by over 2,000 delegates produced a landmark agreement.","The conference, that was attended by over 2,000 delegates, produced a landmark agreement.","The conference, which was attended by over 2,000 delegates, produced a landmark agreement on climate finance.","The conference which was attended by over 2,000 delegates produced a landmark agreement."]','Non-defining: commas + "which." "That" is incorrect. The clause adds extra info about an already-identified event.','medium'),

  -- BLOCK 9: TOEFL Speaking Tasks
  (cid,9,65,'production','[TOEFL Speaking — 45s] Talk about a teacher or professor who had a significant influence on your life. Describe who they are and how they influenced you. Use at least one non-defining relative clause in your response. You have 45 seconds to respond.','',NULL,'Practice: "My teacher, who taught me English for three years, was incredibly patient." Use commas + "who" for people.','medium'),
  (cid,9,66,'production','[TOEFL Speaking — 45s] Describe a book, article, or film that changed the way you think about an important topic. Explain what it was about and why it was significant to you. Try to use a non-defining relative clause. You have 45 seconds to respond.','',NULL,'Example structure: "The book, which was written by X, changed my perspective on Y because..."','medium'),
  (cid,9,67,'production','[TOEFL Speaking — 45s] The reading passage and the lecture both discuss the importance of biodiversity. The lecture, which presented new research, challenged several claims in the reading. Summarize the main points and explain how they relate. You have 45 seconds to respond.','',NULL,'Integrated task: use non-defining clauses to add information naturally. "The professor, who argued that..., suggested that..."','hard'),

  -- BLOCK 10: TOEFL Writing Tasks
  (cid,10,68,'production','[TOEFL Writing] Write a paragraph (150+ words) about a scientific discovery that has had a major impact on human life. Include at least THREE non-defining relative clauses in your response to add additional information about people, places, or things you mention.','',NULL,'Target structures: "Alexander Fleming, who discovered penicillin in 1928, transformed modern medicine." "The discovery, which happened by accident, saved millions of lives." "The laboratory, where he conducted his research, is now a museum."','hard'),
  (cid,10,69,'production','[TOEFL Writing] Some people believe that protecting natural environments should always take priority over economic development. Others argue that economic growth is necessary even if it harms the environment. Discuss both views and give your own opinion. Write at least 150 words. Use non-defining relative clauses where appropriate.','',NULL,'Include structures like: "The Amazon rainforest, which contains 10% of all species on Earth, is under threat." "Environmentalists, whose concerns have been ignored for decades, argue that..."','hard'),
  (cid,10,70,'production','[TOEFL Writing] Integrated task: The reading passage introduces the concept of urban heat islands, which are areas where temperatures are significantly higher than surrounding rural areas. The lecture, which presented contradictory evidence, challenged two key claims in the reading. Write a 150+ word response summarizing the relationship between the reading and the lecture. Use non-defining relative clauses in your analysis.','',NULL,'Practice integrating non-defining clauses: "The author, whose argument rests on X, claims that..." "The professor, who disagrees with this view, argues that..."','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
